CREATE TABLE inv_return (id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,code VARCHAR(64) NOT NULL,company_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT '草稿',row_version INT NOT NULL DEFAULT 0,deleted TINYINT NOT NULL DEFAULT 0,created_by BIGINT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),confirmed_at DATETIME(3) NULL,`remark` VARCHAR(1000) NULL COMMENT 'remark',`requested_by` BIGINT NULL COMMENT 'surplusRequestedBy',`requested_by_name` VARCHAR(150) NULL COMMENT 'surplusRequestedByName',PRIMARY KEY(id),UNIQUE KEY(tenant_id,code),INDEX(tenant_id,deleted,created_at,id),INDEX(tenant_id,warehouse_id,deleted,status));

INSERT INTO inv_return (id,tenant_id,code,company_id,warehouse_id,status,row_version,deleted,created_by,created_at,confirmed_at,`remark`,`requested_by`,`requested_by_name`) SELECT id,tenant_id,code,company_id,warehouse_id,status,row_version,deleted,created_by,created_at,confirmed_at,NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.remark')),'null'),''),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.surplusRequestedBy')),'null'),'') AS SIGNED),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.surplusRequestedByName')),'null'),'') FROM inv_operation WHERE kind='returns';

CREATE TABLE inv_return_line (tenant_id BIGINT NOT NULL,document_id BIGINT NOT NULL,line_no INT NOT NULL,`allocation_id` BIGINT NULL COMMENT 'allocationId',`quantity` DECIMAL(20,6) NULL COMMENT 'quantity',`bin_id` BIGINT NULL COMMENT 'binId',`material_name` VARCHAR(200) NULL COMMENT 'materialName',`issue_code` VARCHAR(64) NULL COMMENT 'issueCode',`returned_amount` DECIMAL(20,2) NULL COMMENT 'returnedAmount',PRIMARY KEY(tenant_id,document_id,line_no),FOREIGN KEY(document_id) REFERENCES inv_return(id) ON DELETE CASCADE);

INSERT INTO inv_return_line SELECT d.tenant_id,d.id,j.n,CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.allocationId')),'null'),'') AS SIGNED),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.quantity')),'null'),'') AS DECIMAL(20,6)),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.binId')),'null'),'') AS SIGNED),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.materialName')),'null'),''),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.issueCode')),'null'),''),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.returnedAmount')),'null'),'') AS DECIMAL(20,2)) FROM inv_operation d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.lines'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) j WHERE kind='returns';

CREATE TABLE inv_transfer (id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,code VARCHAR(64) NOT NULL,company_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT '草稿',row_version INT NOT NULL DEFAULT 0,deleted TINYINT NOT NULL DEFAULT 0,created_by BIGINT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),confirmed_at DATETIME(3) NULL,target_warehouse_id BIGINT NULL,`remark` VARCHAR(1000) NULL COMMENT 'remark',PRIMARY KEY(id),UNIQUE KEY(tenant_id,code),INDEX(tenant_id,deleted,created_at,id),INDEX(tenant_id,warehouse_id,deleted,status));

INSERT INTO inv_transfer (id,tenant_id,code,company_id,warehouse_id,status,row_version,deleted,created_by,created_at,confirmed_at,target_warehouse_id,`remark`) SELECT id,tenant_id,code,company_id,warehouse_id,status,row_version,deleted,created_by,created_at,confirmed_at,target_warehouse_id,NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.remark')),'null'),'') FROM inv_operation WHERE kind='transfers';

CREATE TABLE inv_transfer_line (tenant_id BIGINT NOT NULL,document_id BIGINT NOT NULL,line_no INT NOT NULL,`balance_id` BIGINT NULL COMMENT 'balanceId',`quantity` DECIMAL(20,6) NULL COMMENT 'quantity',`target_bin_id` BIGINT NULL COMMENT 'targetBinId',PRIMARY KEY(tenant_id,document_id,line_no),FOREIGN KEY(document_id) REFERENCES inv_transfer(id) ON DELETE CASCADE);

INSERT INTO inv_transfer_line SELECT d.tenant_id,d.id,j.n,CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.balanceId')),'null'),'') AS SIGNED),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.quantity')),'null'),'') AS DECIMAL(20,6)),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.targetBinId')),'null'),'') AS SIGNED) FROM inv_operation d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.lines'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) j WHERE kind='transfers';

CREATE TABLE inv_count (id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,code VARCHAR(64) NOT NULL,company_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT '草稿',row_version INT NOT NULL DEFAULT 0,deleted TINYINT NOT NULL DEFAULT 0,created_by BIGINT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),confirmed_at DATETIME(3) NULL,`remark` VARCHAR(1000) NULL COMMENT 'remark',`baseline_at` DATETIME(6) NULL COMMENT 'baselineAt',PRIMARY KEY(id),UNIQUE KEY(tenant_id,code),INDEX(tenant_id,deleted,created_at,id),INDEX(tenant_id,warehouse_id,deleted,status));

INSERT INTO inv_count (id,tenant_id,code,company_id,warehouse_id,status,row_version,deleted,created_by,created_at,confirmed_at,`remark`,`baseline_at`) SELECT id,tenant_id,code,company_id,warehouse_id,status,row_version,deleted,created_by,created_at,confirmed_at,NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.remark')),'null'),''),CAST(REPLACE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.baselineAt')),'null'),''),'T',' ') AS DATETIME(6)) FROM inv_operation WHERE kind='counts';

CREATE TABLE inv_count_line (tenant_id BIGINT NOT NULL,document_id BIGINT NOT NULL,line_no INT NOT NULL,`balance_id` BIGINT NULL COMMENT 'balanceId',`baseline_quantity` DECIMAL(20,6) NULL COMMENT 'baselineQuantity',`counted_quantity` DECIMAL(20,6) NULL COMMENT 'countedQuantity',`unit_cost` DECIMAL(20,6) NULL COMMENT 'unitCost',`material_name` VARCHAR(200) NULL COMMENT 'materialName',`bin_name` VARCHAR(150) NULL COMMENT 'binName',`batch_code` VARCHAR(64) NULL COMMENT 'batchCode',`observed_quantity` DECIMAL(20,6) NULL COMMENT 'observedQuantity',`counted_at` DATETIME(6) NULL COMMENT 'countedAt',`difference` DECIMAL(20,6) NULL COMMENT 'difference',PRIMARY KEY(tenant_id,document_id,line_no),FOREIGN KEY(document_id) REFERENCES inv_count(id) ON DELETE CASCADE);

INSERT INTO inv_count_line SELECT d.tenant_id,d.id,j.n,CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.balanceId')),'null'),'') AS SIGNED),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.baselineQuantity')),'null'),'') AS DECIMAL(20,6)),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.countedQuantity')),'null'),'') AS DECIMAL(20,6)),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.unitCost')),'null'),'') AS DECIMAL(20,6)),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.materialName')),'null'),''),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.binName')),'null'),''),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.batchCode')),'null'),''),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.observedQuantity')),'null'),'') AS DECIMAL(20,6)),CAST(REPLACE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.countedAt')),'null'),''),'T',' ') AS DATETIME(6)),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.difference')),'null'),'') AS DECIMAL(20,6)) FROM inv_operation d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.lines'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) j WHERE kind='counts';

CREATE TABLE inv_opening (id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,code VARCHAR(64) NOT NULL,company_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT '草稿',row_version INT NOT NULL DEFAULT 0,deleted TINYINT NOT NULL DEFAULT 0,created_by BIGINT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),confirmed_at DATETIME(3) NULL,`remark` VARCHAR(1000) NULL COMMENT 'remark',`conversion_material_id` BIGINT NULL COMMENT 'conversionMaterialId',`receipt_id` BIGINT NULL COMMENT 'receiptId',`receipt_code` VARCHAR(64) NULL COMMENT 'receiptCode',PRIMARY KEY(id),UNIQUE KEY(tenant_id,code),INDEX(tenant_id,deleted,created_at,id),INDEX(tenant_id,warehouse_id,deleted,status));

INSERT INTO inv_opening (id,tenant_id,code,company_id,warehouse_id,status,row_version,deleted,created_by,created_at,confirmed_at,`remark`,`conversion_material_id`,`receipt_id`,`receipt_code`) SELECT id,tenant_id,code,company_id,warehouse_id,status,row_version,deleted,created_by,created_at,confirmed_at,NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.remark')),'null'),''),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.conversionMaterialId')),'null'),'') AS SIGNED),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.receiptId')),'null'),'') AS SIGNED),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.receiptCode')),'null'),'') FROM inv_operation WHERE kind='openings';

CREATE TABLE inv_opening_line (tenant_id BIGINT NOT NULL,document_id BIGINT NOT NULL,line_no INT NOT NULL,`material_id` BIGINT NULL COMMENT 'materialId',`quantity` DECIMAL(20,6) NULL COMMENT 'quantity',`unit_price` DECIMAL(20,6) NULL COMMENT 'unitPrice',`bin_id` BIGINT NULL COMMENT 'binId',`batch_code` VARCHAR(64) NULL COMMENT 'batchCode',`supplier_batch` VARCHAR(100) NULL COMMENT 'supplierBatch',`production_date` DATE NULL COMMENT 'productionDate',`expiry_date` DATE NULL COMMENT 'expiryDate',`legacy_stock_id` BIGINT NULL COMMENT 'legacyStockId',`allocated_fee` DECIMAL(20,2) NULL COMMENT 'allocatedFee',`material_name` VARCHAR(200) NULL COMMENT 'materialName',`balance_id` BIGINT NULL COMMENT 'balanceId',`warehouse_id` BIGINT NULL COMMENT 'warehouseId',`balance_version` INT NULL COMMENT 'balanceVersion',PRIMARY KEY(tenant_id,document_id,line_no),FOREIGN KEY(document_id) REFERENCES inv_opening(id) ON DELETE CASCADE);

INSERT INTO inv_opening_line SELECT d.tenant_id,d.id,j.n,CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.materialId')),'null'),'') AS SIGNED),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.quantity')),'null'),'') AS DECIMAL(20,6)),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.unitPrice')),'null'),'') AS DECIMAL(20,6)),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.binId')),'null'),'') AS SIGNED),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.batchCode')),'null'),''),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.supplierBatch')),'null'),''),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.productionDate')),'null'),''),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.expiryDate')),'null'),''),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.legacyStockId')),'null'),'') AS SIGNED),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.allocatedFee')),'null'),'') AS DECIMAL(20,2)),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.materialName')),'null'),''),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.balanceId')),'null'),'') AS SIGNED),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.warehouseId')),'null'),'') AS SIGNED),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.value,'$.balanceVersion')),'null'),'') AS SIGNED) FROM inv_operation d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.lines'),JSON_ARRAY()),'$[*]' COLUMNS(n FOR ORDINALITY,value JSON PATH '$')) j WHERE kind='openings';

CREATE TABLE inv_reversal (id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,code VARCHAR(64) NOT NULL,company_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT '草稿',row_version INT NOT NULL DEFAULT 0,deleted TINYINT NOT NULL DEFAULT 0,created_by BIGINT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),confirmed_at DATETIME(3) NULL,`remark` VARCHAR(1000) NULL COMMENT 'remark',`source_kind` VARCHAR(24) NULL COMMENT 'sourceKind',`source_id` BIGINT NULL COMMENT 'sourceId',`source_code` VARCHAR(64) NULL COMMENT 'sourceCode',PRIMARY KEY(id),UNIQUE KEY(tenant_id,code),INDEX(tenant_id,deleted,created_at,id),INDEX(tenant_id,warehouse_id,deleted,status));

INSERT INTO inv_reversal (id,tenant_id,code,company_id,warehouse_id,status,row_version,deleted,created_by,created_at,confirmed_at,`remark`,`source_kind`,`source_id`,`source_code`) SELECT id,tenant_id,code,company_id,warehouse_id,status,row_version,deleted,created_by,created_at,confirmed_at,NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.remark')),'null'),''),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.sourceKind')),'null'),''),CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.sourceId')),'null'),'') AS SIGNED),NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.sourceCode')),'null'),'') FROM inv_operation WHERE kind='reversals';

CREATE VIEW v_inv_operation AS SELECT d.id,d.tenant_id,d.code,d.company_id,d.warehouse_id,d.status,d.row_version,d.deleted,d.created_by,d.created_at,d.confirmed_at,'returns' kind,NULL target_warehouse_id,d.requested_by surplus_requested_by,JSON_OBJECT('remark',COALESCE(CAST(d.`remark` AS CHAR),''),'surplusRequestedBy',COALESCE(CAST(d.`requested_by` AS CHAR),''),'surplusRequestedByName',COALESCE(CAST(d.`requested_by_name` AS CHAR),''),'lines',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('allocationId',COALESCE(CAST(r.`allocation_id` AS CHAR),''),'quantity',COALESCE(CAST(r.`quantity` AS CHAR),''),'binId',COALESCE(CAST(r.`bin_id` AS CHAR),''),'materialName',COALESCE(CAST(r.`material_name` AS CHAR),''),'issueCode',COALESCE(CAST(r.`issue_code` AS CHAR),''),'returnedAmount',COALESCE(CAST(r.`returned_amount` AS CHAR),''))) OVER(ORDER BY r.line_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM inv_return_line r WHERE r.tenant_id=d.tenant_id AND r.document_id=d.id LIMIT 1),JSON_ARRAY())) payload FROM inv_return d UNION ALL SELECT d.id,d.tenant_id,d.code,d.company_id,d.warehouse_id,d.status,d.row_version,d.deleted,d.created_by,d.created_at,d.confirmed_at,'transfers' kind,d.target_warehouse_id target_warehouse_id,NULL surplus_requested_by,JSON_OBJECT('remark',COALESCE(CAST(d.`remark` AS CHAR),''),'targetWarehouseId',CAST(d.target_warehouse_id AS CHAR),'lines',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('balanceId',COALESCE(CAST(r.`balance_id` AS CHAR),''),'quantity',COALESCE(CAST(r.`quantity` AS CHAR),''),'targetBinId',COALESCE(CAST(r.`target_bin_id` AS CHAR),''))) OVER(ORDER BY r.line_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM inv_transfer_line r WHERE r.tenant_id=d.tenant_id AND r.document_id=d.id LIMIT 1),JSON_ARRAY())) payload FROM inv_transfer d UNION ALL SELECT d.id,d.tenant_id,d.code,d.company_id,d.warehouse_id,d.status,d.row_version,d.deleted,d.created_by,d.created_at,d.confirmed_at,'counts' kind,NULL target_warehouse_id,NULL surplus_requested_by,JSON_OBJECT('remark',COALESCE(CAST(d.`remark` AS CHAR),''),'baselineAt',COALESCE(DATE_FORMAT(d.`baseline_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'lines',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('balanceId',COALESCE(CAST(r.`balance_id` AS CHAR),''),'baselineQuantity',COALESCE(CAST(r.`baseline_quantity` AS CHAR),''),'countedQuantity',COALESCE(CAST(r.`counted_quantity` AS CHAR),''),'unitCost',COALESCE(CAST(r.`unit_cost` AS CHAR),''),'materialName',COALESCE(CAST(r.`material_name` AS CHAR),''),'binName',COALESCE(CAST(r.`bin_name` AS CHAR),''),'batchCode',COALESCE(CAST(r.`batch_code` AS CHAR),''),'observedQuantity',COALESCE(CAST(r.`observed_quantity` AS CHAR),''),'countedAt',COALESCE(DATE_FORMAT(r.`counted_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'difference',COALESCE(CAST(r.`difference` AS CHAR),''))) OVER(ORDER BY r.line_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM inv_count_line r WHERE r.tenant_id=d.tenant_id AND r.document_id=d.id LIMIT 1),JSON_ARRAY())) payload FROM inv_count d UNION ALL SELECT d.id,d.tenant_id,d.code,d.company_id,d.warehouse_id,d.status,d.row_version,d.deleted,d.created_by,d.created_at,d.confirmed_at,'openings' kind,NULL target_warehouse_id,NULL surplus_requested_by,JSON_OBJECT('remark',COALESCE(CAST(d.`remark` AS CHAR),''),'conversionMaterialId',COALESCE(CAST(d.`conversion_material_id` AS CHAR),''),'receiptId',COALESCE(CAST(d.`receipt_id` AS CHAR),''),'receiptCode',COALESCE(CAST(d.`receipt_code` AS CHAR),''),'lines',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('materialId',COALESCE(CAST(r.`material_id` AS CHAR),''),'quantity',COALESCE(CAST(r.`quantity` AS CHAR),''),'unitPrice',COALESCE(CAST(r.`unit_price` AS CHAR),''),'binId',COALESCE(CAST(r.`bin_id` AS CHAR),''),'batchCode',COALESCE(CAST(r.`batch_code` AS CHAR),''),'supplierBatch',COALESCE(CAST(r.`supplier_batch` AS CHAR),''),'productionDate',COALESCE(DATE_FORMAT(r.`production_date`,'%Y-%m-%d'),''),'expiryDate',COALESCE(DATE_FORMAT(r.`expiry_date`,'%Y-%m-%d'),''),'legacyStockId',COALESCE(CAST(r.`legacy_stock_id` AS CHAR),''),'allocatedFee',COALESCE(CAST(r.`allocated_fee` AS CHAR),''),'materialName',COALESCE(CAST(r.`material_name` AS CHAR),''),'balanceId',COALESCE(CAST(r.`balance_id` AS CHAR),''),'warehouseId',COALESCE(CAST(r.`warehouse_id` AS CHAR),''),'balanceVersion',COALESCE(CAST(r.`balance_version` AS CHAR),''))) OVER(ORDER BY r.line_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM inv_opening_line r WHERE r.tenant_id=d.tenant_id AND r.document_id=d.id LIMIT 1),JSON_ARRAY())) payload FROM inv_opening d UNION ALL SELECT d.id,d.tenant_id,d.code,d.company_id,d.warehouse_id,d.status,d.row_version,d.deleted,d.created_by,d.created_at,d.confirmed_at,'reversals' kind,NULL target_warehouse_id,NULL surplus_requested_by,JSON_OBJECT('remark',COALESCE(CAST(d.`remark` AS CHAR),''),'sourceKind',COALESCE(CAST(d.`source_kind` AS CHAR),''),'sourceId',COALESCE(CAST(d.`source_id` AS CHAR),''),'sourceCode',COALESCE(CAST(d.`source_code` AS CHAR),''),'lines',JSON_ARRAY()) payload FROM inv_reversal d;

CREATE VIEW v_inv_operation_material AS SELECT r.tenant_id,r.document_id,r.line_no,b.material_id material_id FROM inv_return_line r JOIN inv_issue_allocation a ON a.tenant_id=r.tenant_id AND a.id=r.allocation_id JOIN inv_balance b ON b.tenant_id=a.tenant_id AND b.id=a.balance_id UNION ALL SELECT r.tenant_id,r.document_id,r.line_no,b.material_id material_id FROM inv_transfer_line r JOIN inv_balance b ON b.tenant_id=r.tenant_id AND b.id=r.balance_id UNION ALL SELECT r.tenant_id,r.document_id,r.line_no,b.material_id material_id FROM inv_count_line r JOIN inv_balance b ON b.tenant_id=r.tenant_id AND b.id=r.balance_id UNION ALL SELECT r.tenant_id,r.document_id,r.line_no,r.material_id material_id FROM inv_opening_line r;

RENAME TABLE inv_operation TO migration_v71_inventory_operation_archive;
